// n8n Code node - "Run Once for All Items" mode

function parseSlovenianDate(str) {
  // "18. 6. 2026" -> "2026-06-18"
  if (!str) return null;
  const parts = str.split('.').map(p => p.trim()).filter(Boolean);
  if (parts.length !== 3) return null;
  const [day, month, year] = parts;
  return `${year}-${month.padStart(2, '0')}-${day.padStart(2, '0')}`;
}

function parseNumber(value) {
  if (typeof value !== 'string') return NaN;

  const hasComma = value.includes(',');
  const hasDot = value.includes('.');

  let normalized = value;

  if (hasComma && hasDot) {
    // assume dot = thousand separator, comma = decimal
    normalized = value.replace(/\./g, '').replace(',', '.');
  } else if (hasComma) {
    // comma as decimal
    normalized = value.replace(',', '.');
  }

  return parseFloat(normalized);
}

function mapType(sign) {
  if (sign === '-') return 'withdrawal';
  if (sign === '+') return 'deposit';
  return 'transfer'; // fallback for unexpected values
}

function emptyToNull(val) {
  return val === '' || val === undefined ? null : val;
}

const results = [];

var transactions = $json.data;

for (const raw of transactions) {

  const type = mapType(raw['+/-']);
  const amount = Math.abs(parseNumber(raw['Znesek'])).toFixed(2);
  const date = parseSlovenianDate(raw['Datum plačila']);
  const bookDate = parseSlovenianDate(raw['Datum poravnave']);

  const counterpartyName = emptyToNull(raw['Naziv prejemnika/plačnika']) || raw['Namen'] || 'Unknown';
  const counterpartyIban = emptyToNull(raw['Račun prejemnika/plačnika']);
  const counterpartyBic = emptyToNull(raw['BIC koda']);
  const counterpartyAddress = emptyToNull(raw['Naslov prejemnika/plačnika']);

  const normalized = {
    id:`nlb-savings-${raw['ID transakcije']}`,
    account: 'nlb-savings',
    type,
    date,
    amount,
    currency_code: raw['Valuta'] || null,
    description: raw['Namen'] || '',
    category_name: emptyToNull(raw['Kategorija']),

    // Opposing account, assigned to source_* or destination_*
    // depending on transaction direction
    ...(type === 'withdrawal'
      ? {
          destination_name: counterpartyName,
          destination_iban: counterpartyIban,
          destination_bic: counterpartyBic,
        }
      : {
          source_name: counterpartyName,
          source_iban: counterpartyIban,
          source_bic: counterpartyBic,
        }),

    external_id: emptyToNull(raw['ID transakcije']),
    internal_reference: emptyToNull(raw['Referenca prejemnika']),

    payment_date: date,
    book_date: bookDate,

    tags: [raw['Status']].filter(Boolean),

    // Fields without a direct Firefly III equivalent get folded into notes
    notes: [
      raw['Status'] ? `Status: ${raw['Status']}` : null,
      raw['Menjalni tečaj'] ? `Menjalni tečaj: ${raw['Menjalni tečaj']}` : null,
      raw['Dodatni stroški'] ? `Dodatni stroški: ${raw['Dodatni stroški']}` : null,
      counterpartyAddress ? `Naslov: ${counterpartyAddress}` : null,
    ]
      .filter(Boolean)
      .join(' | ') || null,

    raw,
  };



  results.push(normalized);
}

return {json: {...$json, data: results}};

